import { app, BrowserWindow, ipcMain } from 'electron';
import path from 'path';
import { spawn, ChildProcess } from 'child_process';
import fs from 'fs';

// Store the backend server process
let backendProcess: ChildProcess | null = null;
let isQuitting = false;

// Safe console.log that handles EPIPE
function safeLog(prefix: string, message: string): void {
  if (isQuitting) return;
  try {
    // Use process.stdout.write directly with error handling
    process.stdout.write(`${prefix} ${message}\n`, (err) => {
      // Ignore EPIPE and other write errors
      if (err && err.message?.includes('EPIPE')) {
        // Mark as quitting to prevent further logs
        isQuitting = true;
      }
    });
  } catch (e) {
    // Ignore EPIPE errors during quit
  }
}

// Wait for Vite dev server to be ready
async function waitForVite(maxAttempts: number = 30): Promise<boolean> {
  const http = await import('http');
  for (let i = 0; i < maxAttempts; i++) {
    try {
      await new Promise((resolve, reject) => {
        const req = http.get('http://localhost:5173', (res) => {
          resolve(res);
        });
        req.on('error', reject);
        req.setTimeout(1000, () => {
          req.destroy();
          reject(new Error('timeout'));
        });
      });
      return true;
    } catch {
      await new Promise(r => setTimeout(r, 500));
    }
  }
  return false;
}

// Create the browser window
async function createWindow(): Promise<BrowserWindow> {
  const mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 900,
    minHeight: 600,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
    titleBarStyle: 'hidden',
    trafficLightPosition: { x: 12, y: 12 },
    show: false, // Don't show until loaded
  });

  // Load the app
  // Check if we're in development (Vite dev server should be running)
  const isDev = process.env.NODE_ENV === 'development' || !fs.existsSync(path.join(__dirname, '..', 'apps', 'web', 'dist', 'index.html'));

  if (isDev) {
    // Wait for Vite dev server to be ready
    safeLog('[Main]', 'Waiting for Vite dev server...');
    const viteReady = await waitForVite();
    if (!viteReady) {
      safeLog('[Main]', 'Vite dev server not available, loading anyway...');
    }
    mainWindow.loadURL('http://localhost:5173');
    mainWindow.webContents.openDevTools();
  } else {
    // Load production build
    mainWindow.loadFile(path.join(__dirname, '..', 'apps', 'web', 'dist', 'index.html'));
  }

  mainWindow.once('ready-to-show', () => {
    mainWindow.show();
  });

  return mainWindow;
}

// Start the backend server
function startBackend(): void {
  safeLog('[Main]', 'Starting backend server...');

  backendProcess = spawn('npx', ['tsx', 'apps/server/src/index.ts'], {
    cwd: path.join(__dirname, '..', '..'),
    stdio: 'pipe',
  });

  backendProcess.stdout?.on('data', (data: Buffer) => {
    safeLog('[Backend]', data.toString().trim());
  });

  backendProcess.stderr?.on('data', (data: Buffer) => {
    safeLog('[Backend Error]', data.toString().trim());
  });

  backendProcess.on('close', (code: number | null) => {
    safeLog('[Backend]', `Process exited with code ${code}`);
  });

  backendProcess.on('error', (err: Error) => {
    safeLog('[Backend]', `Failed to start: ${err.message}`);
  });
}

// Stop the backend server
function stopBackend(): void {
  if (backendProcess) {
    safeLog('[Main]', 'Stopping backend server...');
    backendProcess.kill();
    backendProcess = null;
  }
}

// App event handlers
app.whenReady().then(async () => {
  // Start backend server
  startBackend();

  // Create window after a short delay to let backend start
  setTimeout(async () => {
    await createWindow();
  }, 2000);

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  isQuitting = true;
  stopBackend();
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('before-quit', () => {
  isQuitting = true;
  stopBackend();
});

app.on('will-quit', () => {
  isQuitting = true;
  stopBackend();
});

// Handle EPIPE errors globally
process.on('uncaughtException', (error: Error) => {
  if (error.message?.includes('EPIPE')) {
    // Ignore EPIPE errors - they happen when stdout is closed
    isQuitting = true;
    return;
  }
  // Re-throw other errors
  throw error;
});

@import "./styles/design-tokens.css";

/* Electron window drag regions */
.app-drag-region {
  -webkit-app-region: drag;
  app-region: drag;
}

/* Prevent dragging on interactive elements within draggable regions */
.app-drag-region button,
.app-drag-region input,
.app-drag-region select,
.app-drag-region a,
.app-no-drag {
  -webkit-app-region: no-drag;
  app-region: no-drag;
}

/* macOS traffic light padding */
.mac-traffic-light-padding {
  padding-left: 80px;
}

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --font-size: 16px;
    --background: #ffffff;
    --foreground: oklch(0.145 0 0);
    --card: #ffffff;
    --card-foreground: oklch(0.145 0 0);
    --popover: oklch(1 0 0);
    --popover-foreground: oklch(0.145 0 0);
    --primary: #030213;
    --primary-foreground: oklch(1 0 0);
    --secondary: oklch(0.95 0.0058 264.53);
    --secondary-foreground: #030213;
    --muted: #ececf0;
    --muted-foreground: #717182;
    --accent: #e9ebef;
    --accent-foreground: #030213;
    --destructive: #d4183d;
    --destructive-foreground: #ffffff;
    --border: rgba(0, 0, 0, 0.1);
    --input: transparent;
    --input-background: #f3f3f5;
    --switch-background: #cbced4;
    --font-weight-medium: 500;
    --font-weight-normal: 400;
    --font-weight-light: 300;
    --ring: oklch(0.708 0 0);
    --chart-1: oklch(0.646 0.222 41.116);
    --chart-2: oklch(0.6 0.118 184.704);
    --chart-3: oklch(0.398 0.07 227.392);
    --chart-4: oklch(0.828 0.189 84.429);
    --chart-5: oklch(0.769 0.188 70.08);
    --radius: 0.625rem;
    --sidebar: oklch(0.985 0 0);
    --sidebar-foreground: oklch(0.145 0 0);
    --sidebar-primary: #030213;
    --sidebar-primary-foreground: oklch(0.985 0 0);
    --sidebar-accent: oklch(0.97 0 0);
    --sidebar-accent-foreground: oklch(0.205 0 0);
    --sidebar-border: oklch(0.922 0 0);
    --sidebar-ring: oklch(0.708 0 0);

    /* Map to Tailwind color variables */
    --color-background: var(--background);
    --color-foreground: var(--foreground);
    --color-card: var(--card);
    --color-card-foreground: var(--card-foreground);
    --color-popover: var(--popover);
    --color-popover-foreground: var(--popover-foreground);
    --color-primary: var(--primary);
    --color-primary-foreground: var(--primary-foreground);
    --color-secondary: var(--secondary);
    --color-secondary-foreground: var(--secondary-foreground);
    --color-muted: var(--muted);
    --color-muted-foreground: var(--muted-foreground);
    --color-accent: var(--accent);
    --color-accent-foreground: var(--accent-foreground);
    --color-destructive: var(--destructive);
    --color-destructive-foreground: var(--destructive-foreground);
    --color-border: var(--border);
    --color-input: var(--input);
    --color-input-background: var(--input-background);
    --color-switch-background: var(--switch-background);
    --color-ring: var(--ring);
    --color-chart-1: var(--chart-1);
    --color-chart-2: var(--chart-2);
    --color-chart-3: var(--chart-3);
    --color-chart-4: var(--chart-4);
    --color-chart-5: var(--chart-5);
    --radius-sm: calc(var(--radius) - 4px);
    --radius-md: calc(var(--radius) - 2px);
    --radius-lg: var(--radius);
    --radius-xl: calc(var(--radius) + 4px);
    --color-sidebar: var(--sidebar);
    --color-sidebar-foreground: var(--sidebar-foreground);
    --color-sidebar-primary: var(--sidebar-primary);
    --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
    --color-sidebar-accent: var(--sidebar-accent);
    --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
    --color-sidebar-border: var(--sidebar-border);
    --color-sidebar-ring: var(--sidebar-ring);
  }

  .dark {
    --background: oklch(0.145 0 0);
    --foreground: oklch(0.985 0 0);
    --card: oklch(0.145 0 0);
    --card-foreground: oklch(0.985 0 0);
    --popover: oklch(0.145 0 0);
    --popover-foreground: oklch(0.985 0 0);
    --primary: oklch(0.985 0 0);
    --primary-foreground: oklch(0.205 0 0);
    --secondary: oklch(0.269 0 0);
    --secondary-foreground: oklch(0.985 0 0);
    --muted: oklch(0.269 0 0);
    --muted-foreground: oklch(0.708 0 0);
    --accent: oklch(0.269 0 0);
    --accent-foreground: oklch(0.985 0 0);
    --destructive: oklch(0.396 0.141 25.723);
    --destructive-foreground: oklch(0.637 0.237 25.331);
    --border: oklch(0.269 0 0);
    --input: oklch(0.269 0 0);
    --ring: oklch(0.439 0 0);
    --chart-1: oklch(0.488 0.243 264.376);
    --chart-2: oklch(0.696 0.17 162.48);
    --chart-3: oklch(0.769 0.188 70.08);
    --chart-4: oklch(0.627 0.265 303.9);
    --chart-5: oklch(0.645 0.246 16.439);
    --sidebar: oklch(0.205 0 0);
    --sidebar-foreground: oklch(0.985 0 0);
    --sidebar-primary: oklch(0.488 0.243 264.376);
    --sidebar-primary-foreground: oklch(0.985 0 0);
    --sidebar-accent: oklch(0.269 0 0);
    --sidebar-accent-foreground: oklch(0.985 0 0);
    --sidebar-border: oklch(0.269 0 0);
    --sidebar-ring: oklch(0.439 0 0);
  }

  * {
    @apply m-0 p-0 box-border;
    border-color: var(--color-border);
  }

  *:focus-visible {
    outline: 2px solid var(--color-ring);
    outline-offset: 2px;
  }

  html {
    @apply h-full overflow-hidden;
    font-size: var(--font-size);
  }

  body {
    @apply h-screen font-sans leading-normal overflow-hidden antialiased;
    background-color: var(--color-background);
    color: var(--color-foreground);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-feature-settings: "cv11", "ss01";
    font-variation-settings: "opsz" 32;
  }

  #root {
    @apply h-screen;
  }

  h1 {
    font-size: 1.125rem;   /* 18px */
    font-weight: 600;
    line-height: 1.25;
  }

  h2 {
    font-size: 1.0625rem;  /* 17px */
    font-weight: 600;
    line-height: 1.25;
  }

  h3 {
    font-size: 1rem;       /* 16px */
    font-weight: 500;
    line-height: 1.25;
  }

  h4 {
    font-size: 0.9375rem;  /* 15px - same as body */
    font-weight: 600;
    line-height: 1.25;
  }

  h5 {
    font-size: 0.9375rem;  /* 15px - same as body */
    font-weight: 500;
    line-height: 1.25;
  }

  h6 {
    font-size: 0.875rem;   /* 14px */
    font-weight: 600;
    line-height: 1.25;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  label {
    font-size: 1rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.5;
  }

  button {
    font-size: 1rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.5;
  }

  input {
    font-size: 1rem;
    font-weight: var(--font-weight-normal);
    line-height: 1.5;
  }
}

@layer components {
  /* Scrollbar styles */
  ::-webkit-scrollbar {
    @apply w-2 h-2;
  }

  ::-webkit-scrollbar-track {
    @apply bg-transparent;
  }

  ::-webkit-scrollbar-thumb {
    @apply bg-gray-300 rounded;
  }

  ::-webkit-scrollbar-thumb:hover {
    @apply bg-gray-400;
  }

  /* Code block wrapper styles */
  .code-block-wrapper {
    @apply my-4;
  }

  /* Remove default pre/code background when using SyntaxHighlighter */
  .markdown-content pre {
    @apply m-0;
    background: transparent !important;
  }
}

@layer utilities {
  .animate-fade-in {
    animation: fadeIn 0.2s ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-pulse-slow {
    animation: pulse-slow 2s ease-in-out infinite;
  }

  @keyframes pulse-slow {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.5;
    }
  }

  /* Streaming cursor blink */
  .animate-cursor-blink {
    animation: cursorBlink 0.8s step-end infinite;
  }

  @keyframes cursorBlink {
    0%,
    50% {
      opacity: 1;
    }
    51%,
    100% {
      opacity: 0;
    }
  }

  /* Shimmer loading effect */
  .animate-shimmer {
    animation: shimmer 1.5s ease-in-out infinite;
    background: linear-gradient(
      90deg,
      oklch(0.97 0 0) 0%,
      oklch(0.99 0 0) 50%,
      oklch(0.97 0 0) 100%
    );
    background-size: 200% 100%;
  }

  @keyframes shimmer {
    0% {
      background-position: 200% 0;
    }
    100% {
      background-position: -200% 0;
    }
  }

  /* Smooth streaming text - optimized for performance */
  .streaming-content {
    contain: content;
    will-change: contents;
    /* Text naturally accumulates without animation - modern approach */
    /* Only apply subtle fade to newly added content via React */
    animation: none;
  }

  /* Subtle fade-in for streaming content updates */
  .animate-fade-in-subtle {
    animation: fadeInSubtle 0.3s ease-out;
  }

  @keyframes fadeInSubtle {
    from {
      opacity: 0.7;
    }
    to {
      opacity: 1;
    }
  }

  .streaming-markdown {
    contain: content;
  }

  .streaming-cursor {
    display: inline-block;
    width: 2px;
    height: 1em;
    background-color: currentColor;
    margin-left: 2px;
    vertical-align: text-bottom;
    animation: cursorBlink 0.8s step-end infinite;
  }

  /* Coral-colored streaming cursor */
  .streaming-cursor-coral {
    display: inline-block;
    width: 2px;
    height: 1em;
    background-color: #ff6b6b;
    margin-left: 2px;
    vertical-align: text-bottom;
    animation: cursorBlink 0.8s step-end infinite;
  }

  /* ===== Flowtoken-style Character Animation ===== */

  /* Flowtoken animation keyframes */
  @keyframes ft-fadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes ft-slideUp {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes ft-blurIn {
    0% {
      opacity: 0;
      filter: blur(10px);
    }
    100% {
      opacity: 1;
      filter: blur(0);
    }
  }

  @keyframes ft-dropIn {
    0% {
      opacity: 0;
      transform: translateY(-15px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes ft-wave {
    0% {
      opacity: 0;
      transform: translateY(5px);
    }
    50% {
      opacity: 1;
      transform: translateY(-2px);
    }
    100% {
      transform: translateY(0);
    }
  }

  @keyframes ft-highlight {
    0% {
      background-color: rgba(255, 200, 100, 0.5);
    }
    100% {
      background-color: transparent;
    }
  }

  /* Container for animated markdown during streaming */
  .streaming-markdown {
    contain: content;
    will-change: contents;
  }

  /* Each animated character gets this class */
  .char-animated,
  .char-sp,
  .ft-char,
  .fc {
    display: inline;
    animation: charFadeInUp 0.8s ease-in-out both;
  }

  /* Fade in up animation - inspired by Flowtoken */
  @keyframes charFadeInUp {
    from {
      opacity: 0;
      transform: translateY(4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Alternative animations (Flowtoken provides these) */

  /* Blur in effect */
  .char-animated-blur {
    animation: charBlurIn 0.8s ease-in-out both;
  }

  @keyframes charBlurIn {
    from {
      opacity: 0;
      filter: blur(8px);
    }
    to {
      opacity: 1;
      filter: blur(0);
    }
  }

  /* Drop in effect */
  .char-animated-drop {
    animation: charDropIn 0.8s ease-in-out both;
  }

  @keyframes charDropIn {
    from {
      opacity: 0;
      transform: translateY(-12px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Wave effect */
  .char-animated-wave {
    animation: charWave 0.8s ease-in-out both;
  }

  @keyframes charWave {
    0%,
    100% {
      transform: translateY(0);
    }
    25% {
      transform: translateY(-3px);
    }
    50% {
      transform: translateY(0);
    }
    75% {
      transform: translateY(3px);
    }
  }

  /* Highlight effect */
  .char-animated-highlight {
    animation: charHighlight 0.8s ease-in-out both;
  }

  @keyframes charHighlight {
    from {
      background-color: rgba(255, 107, 107, 0.3);
    }
    to {
      background-color: transparent;
    }
  }

  /* For completed messages - fade in the whole block */
  .animate-fade-in-up {
    animation: smoothFadeInUp 0.8s ease-in-out;
  }

  @keyframes smoothFadeInUp {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Spinner rotation */
  .animate-spin-slow {
    animation: spin 1.5s linear infinite;
  }

  @keyframes spin {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useChat } from "@/contexts/ChatContext";
import {
  ChatSidebarContainer,
  ChatInputContainer,
  MessageList,
} from "@/components/chat";
import { RightSidebar } from "@/components/RightSidebar";
import { AuthPage } from "@/pages/AuthPage";
import { ChevronLeft, PanelRightOpen } from "lucide-react";

function App() {
  const { isLoggedIn, isLoading: authLoading } = useAuth();
  const { currentChat, messages, isStreaming } = useChat();
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);

  // Show auth page if not logged in
  if (!isLoggedIn && !authLoading) {
    return <AuthPage />;
  }

  // Show loading state
  if (authLoading) {
    return (
      <div className="fixed inset-0 bg-bg-base flex flex-col items-center justify-center gap-4">
        <div className="w-10 h-10 border-[3px] border-purple-400/30 border-t-purple-500 rounded-full animate-spin" />
        <p className="text-text-secondary">Loading...</p>
      </div>
    );
  }

  const isHomeView = !currentChat && messages.length === 0;

  return (
    <div className="relative h-screen flex overflow-hidden bg-zinc-50">
      {/* Left Sidebar - Chat History */}
      <ChatSidebarContainer />

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden min-w-0">
        {isHomeView ? (
          /* Home View */
          <div className="flex-1 flex flex-col items-center justify-center px-6 py-10 overflow-hidden bg-white">
            {/* Draggable header area for macOS */}
            <div className="absolute top-0 left-[280px] right-0 h-12 app-drag-region mac-traffic-light-padding" />
            <div className="mb-8">
              <div className="flex flex-col items-center gap-2">
                <h1 className="font-accent text-4xl font-normal text-text-primary tracking-tighter">
                  Mari berbincang dan berkreasi bersama 🤙
                </h1>
                <p className="text-sm text-text-tertiary mt-1 tracking-wide font-light">
                  Powered by Claude Code and Composio
                </p>
              </div>
            </div>

            <ChatInputContainer variant="home" />
          </div>
        ) : (
          /* Chat View */
          <div className="flex-1 flex h-screen overflow-hidden">
            <div className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden bg-white">
              {/* Chat Header - Draggable on macOS */}
              <div className="flex items-center justify-between px-6 py-3.5 bg-white app-drag-region mac-traffic-light-padding">
                <h1 className="text-sm font-medium text-text-primary tracking-tight">
                  {currentChat?.title || "New chat"}
                </h1>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => setIsRightSidebarOpen(prev => !prev)}
                    className="w-8 h-8 rounded-full bg-zinc-100 flex items-center justify-center hover:bg-zinc-200 transition-colors text-zinc-600 app-no-drag"
                    title={isRightSidebarOpen ? "Hide sidebar" : "Show sidebar"}
                  >
                    {isRightSidebarOpen ? (
                      <ChevronLeft className="w-4 h-4" strokeWidth={1.5} />
                    ) : (
                      <PanelRightOpen className="w-4 h-4" strokeWidth={1.5} />
                    )}
                  </button>
                </div>
              </div>

              {/* Messages */}
              <MessageList messages={messages} isStreaming={isStreaming} />

              {/* Input */}
              <ChatInputContainer variant="chat" />
            </div>

            {/* Right Sidebar */}
            {isRightSidebarOpen && <RightSidebar />}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;

/**
 * ChatSidebar - Presentational component
 * 
 * Pure UI component with no context access. All data and actions come from props.
 */
import { useState, useRef, useEffect } from "react";
import {
  Search,
  PenSquare,
  Settings,
  MoreHorizontal,
  Trash2,
} from "lucide-react";

interface ChatSidebarProps {
  // User data
  user: { displayName?: string; email: string } | null;

  // Workspace data
  currentWorkspace: { id: string; name: string } | null;
  workspaces: { id: string; name: string }[];
  onSwitchWorkspace: (id: string) => void;
  onCreateWorkspace: (name: string, description?: string) => Promise<unknown>;

  // Chat data
  chats: { id: string; title: string }[];
  currentChatId: string | null;
