/**
 * useChatStream - Simple streaming without over-engineering
 *
 * REALITY CHECK:
 * ChatGPT, Claude.ai, etc. achieve smooth streaming because:
 * 1. Their backends send small, frequent chunks (1-10 chars at a time)
 * 2. They use simple React rendering - no fancy tricks
 * 3. The "smoothness" is from consistent chunk timing, not frontend magic
 *
 * If your backend sends big chunks infrequently, NO frontend trick will help.
 */
import { useState, useRef, useCallback } from 'react';
import type { Message, ToolCall, Todo, InlineToolCall, Provider } from '@normie/types';
import { generateId } from '@normie/utils';
import { chatApi } from '@/lib/api';
import { queryClient } from '@/lib/query-client';

// Helper to check if error is a user-initiated abort
function isAbortError(error: unknown): boolean {
  if (error instanceof Error) {
    return error.name === 'AbortError' ||
           error.message?.includes('abort') ||
           error.message?.includes('cancelled') ||
           error.message?.includes('The operation was aborted');
  }
  return false;
}

interface UseChatStreamReturn {
  messages: Message[];
  isStreaming: boolean;
  toolCalls: ToolCall[];
  todos: Todo[];
  generatedTitle: string | null;
  sendMessage: (params: {
    content: string;
    chatId: string;
    chatTitle: string;
    provider: Provider;
    model: string;
    workspaceId: string | null;
    userId: string;
  }, callbacks?: {
    onTitleUpdate?: (title: string) => void;
  }) => Promise<{ chatId: string; chatTitle: string } | null>;
  stopStreaming: (chatId: string, provider: Provider) => Promise<void>;
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  setToolCalls: React.Dispatch<React.SetStateAction<ToolCall[]>>;
  setTodos: React.Dispatch<React.SetStateAction<Todo[]>>;
  loadMessages: (chat: { messages: Message[]; todos?: Todo[]; toolCalls?: ToolCall[] }) => void;
  reset: () => void;
}

export function useChatStream(): UseChatStreamReturn {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [todos, setTodos] = useState<Todo[]>([]);
  const [generatedTitle, setGeneratedTitle] = useState<string | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);

  const reset = useCallback(() => {
    setMessages([]);
    setToolCalls([]);
    setTodos([]);
    setGeneratedTitle(null);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
  }, []);

  const loadMessages = useCallback((chat: { messages: Message[]; todos?: Todo[]; toolCalls?: ToolCall[] }) => {
    setMessages(chat.messages);
    setTodos(chat.todos || []);
    setToolCalls(chat.toolCalls || []);
  }, []);

  const stopStreaming = useCallback(async (chatId: string, provider: Provider) => {
    window.electronAPI?.abortCurrentRequest();
    if (chatId) {
      await chatApi.abort(chatId, provider);
    }
    setIsStreaming(false);
  }, []);

  const sendMessage = useCallback(
    async (
      params: {
        content: string;
        chatId: string;
        chatTitle: string;
        provider: Provider;
        model: string;
        workspaceId: string | null;
        userId: string;
      },
      callbacks?: {
        onTitleUpdate?: (title: string) => void;
      }
    ): Promise<{ chatId: string; chatTitle: string } | null> => {
      const { content, chatId, chatTitle, provider, model, workspaceId, userId } = params;

      if (!content.trim() || isStreaming) return null;

      const userMessage: Message = {
        id: generateId(),
        role: 'user',
        content: content.trim(),
      };

      // Add user message
      setMessages((prev) => [...prev, userMessage]);

      // Create placeholder assistant message
      const assistantMessageId = generateId();
      setMessages((prev) => [
        ...prev,
        {
          id: assistantMessageId,
          role: 'assistant',
          content: '',
          reasoning: '',
          inlineToolCalls: [],
        },
      ]);

      setIsStreaming(true);

      try {
        const reader = await chatApi.send({
          content,
          chatId,
          provider,
          model,
          workspaceId,
          userId,
        });

        let fullContent = '';
        let fullReasoning = '';
        const pendingToolCalls = new Map<string, string>();

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (!value) continue;

          // Parse SSE data
          const lines = value.split('\n');
          for (const line of lines) {
            if (line.startsWith(':')) continue;
            if (!line.startsWith('data: ')) continue;

            try {
              const data = JSON.parse(line.slice(6));

              switch (data.type) {
                case 'text':
                  if (data.content) {
                    if (data.isReasoning) {
                      fullReasoning += data.content;
                    } else {
                      fullContent += data.content;
                    }
                    // Simple React update - this is how most apps do it
                    setMessages((prev) =>
                      prev.map((m) =>
                        m.id === assistantMessageId
                          ? { ...m, content: fullContent, reasoning: fullReasoning }
                          : m
                      )
                    );
                  }
                  break;

                case 'tool_use':
                  if (data.name) {
                    const localToolId = generateId();

                    const toolCall: ToolCall = {
                      id: localToolId,
                      name: data.name,
                      input: data.input || {},
                      status: 'running',
                    };
                    setToolCalls((prev) => [...prev, toolCall]);

                    if (data.id) {
                      pendingToolCalls.set(data.id, localToolId);
                    }

                    const inlineToolCall: InlineToolCall = {
                      id: localToolId,
                      name: data.name,
                      input: data.input || {},
                      status: 'running',
                    };
                    setMessages((prev) =>
                      prev.map((m) =>
                        m.id === assistantMessageId
                          ? {
                              ...m,
                              inlineToolCalls: [
                                ...(m.inlineToolCalls || []),
                                inlineToolCall,
                              ],
                            }
                          : m
                      )
                    );

                    if (data.name === 'TodoWrite' && data.input?.todos) {
                      setTodos(data.input.todos as Todo[]);
                    }
                  }
                  break;

                case 'tool_result':
                  if (data.tool_use_id || data.result !== undefined) {
                    const apiToolId = data.tool_use_id;
                    const localId = apiToolId
                      ? pendingToolCalls.get(apiToolId)
                      : null;

                    if (localId) {
                      setToolCalls((prev) =>
                        prev.map((t) =>
                          t.id === localId
                            ? { ...t, status: 'success', result: data.result }
                            : t
                        )
                      );

                      setMessages((prev) =>
                        prev.map((m) =>
                          m.id === assistantMessageId
                            ? {
                                ...m,
                                inlineToolCalls:
                                  m.inlineToolCalls?.map((t) =>
                                    t.id === localId
                                      ? {
                                          ...t,
                                          status: 'success',
                                          result: data.result,
                                        }
                                      : t
                                  ) || [],
                              }
                            : m
                        )
                      );

                      pendingToolCalls.delete(apiToolId);
                    }
                  }
                  break;

                case 'title_update':
                  // Title was auto-generated by AI after first exchange
                  if (data.title) {
                    setGeneratedTitle(data.title);
                    // Update the chat title in query cache
                    queryClient.setQueryData(['chats', 'list'], (old: unknown) => {
                      if (!old || typeof old !== 'object' || !('chats' in old)) return old;
                      const oldData = old as { chats: Array<{ id: string; title: string }> };
                      return {
                        ...oldData,
                        chats: oldData.chats.map((chat) =>
                          chat.id === chatId ? { ...chat, title: data.title } : chat
                        ),
                      };
                    });
                    // Call the callback if provided
                    callbacks?.onTitleUpdate?.(data.title);
                  }
                  break;

                case 'error':
                  throw new Error(data.message || 'Stream error');
              }
            } catch {
              // Skip parse errors
            }
          }
        }

        // Final update
        setMessages((prev) =>
          prev.map((m) => {
            if (m.id !== assistantMessageId) return m;
            return {
              ...m,
              content: fullContent,
              reasoning: fullReasoning || undefined,
              inlineToolCalls: m.inlineToolCalls?.length
                ? m.inlineToolCalls
                : undefined,
            };
          })
        );

        return { chatId, chatTitle };
      } catch (error) {
        console.error('[useChatStream] Error:', error);

        // Don't show error for user-initiated abort
        if (isAbortError(error)) {
          console.log('[useChatStream] Stream aborted by user, not an error');
          // Clean up: remove empty placeholder or keep accumulated content
          setMessages((prev) =>
            prev.map((m) =>
              m.id === assistantMessageId
                ? {
                    ...m,
                    // Keep accumulated content, clean up reasoning if empty
                    reasoning: m.reasoning || undefined,
                  }
                : m
            )
          );
        } else {
          // Only show error for actual errors (not aborts)
          setMessages((prev) =>
            prev.map((m) =>
              m.id === assistantMessageId
                ? {
                    ...m,
                    content:
                      m.content +
                      `\n\n[Error: ${error instanceof Error ? error.message : 'Unknown error'}]`,
                  }
                : m
            )
          );
        }

        return null;
      } finally {
        setIsStreaming(false);
      }
    },
    [isStreaming]
  );

  return {
    messages,
    isStreaming,
    toolCalls,
    todos,
    generatedTitle,
    sendMessage,
    stopStreaming,
    setMessages,
    setToolCalls,
    setTodos,
    loadMessages,
    reset,
  };
}

/**
 * useChatSender - Send message orchestration
 * 
 * Extracted from ChatContext to keep context stateless.
 * Handles the logic of sending a message and updating state.
 */
import { useCallback, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import type { Chat, Message, Provider, Todo, ToolCall } from '@normie/types';
import { chatKeys } from './useChats';

interface UseChatSenderParams {
  currentChat: Chat | null;
  workspaceId: string | undefined;
  provider: Provider;
  model: string;
  userId: string | undefined;
  messages: Message[];
  todos: Todo[];
  toolCalls: ToolCall[];
  isStreaming: boolean;
  sendStreamMessage: (
    params: {
      content: string;
      chatId: string;
      chatTitle: string;
      provider: Provider;
      model: string;
      workspaceId: string | null;
      userId: string;
    },
    callbacks?: {
      onTitleUpdate?: (title: string) => void;
    }
  ) => Promise<{ chatId: string; chatTitle: string } | null>;
  setCurrentChat: (chat: Chat | null) => void;
}

interface UseChatSenderReturn {
  sendMessage: (content: string) => Promise<void>;
}

export function useChatSender(params: UseChatSenderParams): UseChatSenderReturn {
  const {
    currentChat,
    workspaceId,
    provider,
    model,
    userId,
    messages,
    todos,
    toolCalls,
    isStreaming,
    sendStreamMessage,
    setCurrentChat,
  } = params;

  const queryClient = useQueryClient();
  // Track the generated title for this conversation
  const generatedTitleRef = useRef<string | null>(null);

  const sendMessage = useCallback(
    async (content: string) => {
      if (!content.trim() || isStreaming || !userId) return;

      const chatId = currentChat?.id || crypto.randomUUID();
      const chatTitle =
        currentChat?.title ||
        (content.length > 30 ? content.substring(0, 30) + '...' : content);

      const result = await sendStreamMessage(
        {
          content,
          chatId,
          chatTitle,
          provider,
          model,
          workspaceId: workspaceId || null,
          userId,
        },
        {
          onTitleUpdate: (title) => {
            generatedTitleRef.current = title;
          },
        }
      );

      if (result) {
        // Filter out error messages for final state
        const finalMessages: Message[] = messages.filter((m) =>
          !m.content.startsWith('[Error:')
        );

        // Use the AI-generated title if available, otherwise fallback
        const finalTitle = generatedTitleRef.current || result.chatTitle;

        const updatedChat: Chat = {
          id: result.chatId,
          title: finalTitle,
          provider,
          model,
          updatedAt: Date.now(),
          messages: finalMessages,
          todos,
          toolCalls,
        };

        setCurrentChat(updatedChat);

        // Reset the generated title ref for next conversation
        generatedTitleRef.current = null;

        // Refresh chat list from server
        queryClient.invalidateQueries({ queryKey: ['chats', 'list'] });
      }
    },
    [
      currentChat,
      workspaceId,
      provider,
      model,
      userId,
      messages,
      todos,
      toolCalls,
      isStreaming,
      sendStreamMessage,
      setCurrentChat,
      queryClient,
    ],
  );

  return { sendMessage };
}

/**
 * useCurrentChat - TanStack Query-powered chat loading
 *
 * Replaces the manual loading in useChatActions with TanStack Query.
 * Provides instant cached data + background refetching.
 */
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect } from 'react';
import type { Chat } from '@normie/types';
import { transformApiChat } from '@normie/utils';
import { chatApi } from '@/lib/api';
import { chatKeys } from './useChats';
import { setCurrentChatId } from '@/lib/storage';

interface UseCurrentChatParams {
  workspaceId: string | undefined;
  chatId: string | null;
  enabled: boolean;
}

interface UseCurrentChatReturn {
  chat: Chat | null;
  messages: Chat['messages'];
  todos: Chat['todos'];
  toolCalls: Chat['toolCalls'];
  isLoading: boolean;
  isFetching: boolean;
  error: Error | null;
  prefetchChat: (id: string) => void;
}

export function useCurrentChat(params: UseCurrentChatParams): UseCurrentChatReturn {
  const { workspaceId, chatId, enabled } = params;
  const queryClient = useQueryClient();

  // Query for chat details with messages
  const {
    data: chat,
    isLoading: isLoadingChat,
    isFetching: isFetchingChat,
    error,
  } = useQuery({
    queryKey: chatKeys.detail(chatId!),
    queryFn: async (): Promise<Chat | null> => {
      if (!chatId) return null;
      const chatData = await chatApi.get(chatId);
      return transformApiChat(chatData);
    },
    enabled: enabled && !!chatId,
    staleTime: 5 * 60 * 1000, // 5 minutes - chat data doesn't change often
    gcTime: 10 * 60 * 1000, // Keep in garbage collection for 10 minutes
  });

  // Update localStorage when chat changes
  useEffect(() => {
    if (chatId) {
      setCurrentChatId(chatId);
    }
  }, [chatId]);

  // Prefetch a chat for instant navigation
  const prefetchChat = useCallback(
    (id: string) => {
      if (!id) return;
      queryClient.prefetchQuery({
        queryKey: chatKeys.detail(id),
        queryFn: () => chatApi.get(id),
        staleTime: 5 * 60 * 1000,
      });
    },
    [queryClient]
  );

  return {
    chat: chat ?? null,
    messages: chat?.messages ?? [],
    todos: chat?.todos ?? [],
    toolCalls: chat?.toolCalls ?? [],
    isLoading: isLoadingChat,
    isFetching: isFetchingChat,
    error: error as Error | null,
    prefetchChat,
  };
}

/**
 * useChatNavigation - Navigation without data loading
 *
 * Manages which chat is "current" without blocking on data loading.
 * Data loading is handled separately by useCurrentChat via TanStack Query.
 */
import { useCallback, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { chatKeys } from './useChats';
import { setCurrentChatId } from '@/lib/storage';

interface UseChatNavigationReturn {
  currentChatId: string | null;
  navigateToChat: (chatId: string) => void;
  navigateToNewChat: () => void;
}

export function useChatNavigation(): UseChatNavigationReturn {
  const queryClient = useQueryClient();
  const [currentChatId, setCurrentChatIdState] = useState<string | null>(null);

  const navigateToChat = useCallback((chatId: string) => {
    // Instant - no waiting for data
    setCurrentChatIdState(chatId);
    setCurrentChatId(chatId);

    // Prefetch for instant feel if not already cached
    queryClient.prefetchQuery({
      queryKey: chatKeys.detail(chatId),
      queryFn: async () => {
        const { chatApi } = await import('@/lib/api');
        return chatApi.get(chatId);
      },
      staleTime: 5 * 60 * 1000,
    });
  }, [queryClient]);

  const navigateToNewChat = useCallback(() => {
    setCurrentChatIdState(null);
    setCurrentChatId(null);
  }, []);

  return {
    currentChatId,
    navigateToChat,
    navigateToNewChat,
  };
}

